def resolve(path, cwd, links):
    # Convert relative path to absolute
    if not path.startswith('/'):
        if not cwd.endswith('/'):
            cwd += '/'
        path = cwd + path

    # Split path into components and filter empty ones
    components = [c for c in path.split('/') if c and c != '.']

    # Track current directory and link count
    current = '/'
    link_count = 0
    i = 0

    while i < len(components):
        component = components[i]

        if component == '..':
            # Move to parent directory
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
        else:
            # Append component to current path
            if current == '/':
                current = '/' + component
            else:
                current = current + '/' + component

            # Check if current path is a symlink
            if current in links:
                link_count += 1
                if link_count > 8:
                    return None

                # Get the symlink target
                target = links[current]

                # Resolve the target
                remaining_components = components[i + 1:]

                # Process target: if absolute, start from root; if relative, from parent of link
                if target.startswith('/'):
                    target_components = [c for c in target.split('/') if c and c != '.']
                    current = '/'
                else:
                    # Relative target: resolve relative to parent of symlink
                    if current == '/':
                        parent = '/'
                    else:
                        parent = current.rsplit('/', 1)[0]
                        if not parent:
                            parent = '/'

                    target_components = [c for c in target.split('/') if c and c != '.']
                    current = parent

                # Combine target components with remaining components
                components = target_components + remaining_components
                i = 0
                continue

        i += 1

    # Return result without trailing slash
    if current == '/':
        return '/'
    return current

